import { css } from '@emotion/css';
import cx from 'clsx';
import * as React from 'react';

import { type GrafanaTheme2, type TraceKeyValuePair } from '@grafana/data';
import { Counter, Icon, useStyles2 } from '@grafana/ui';

import type TNil from '../../types/TNil';

import * as markers from './AccordionKeyValues.markers';
import { KeyValuesSummary } from './KeyValuesSummary';
import KeyValuesTable, { type KeyValuesTableLink } from './KeyValuesTable';
import { type AttributePluginPromoGetter } from './pluginPromo/attributePluginPromos';

import { alignIcon } from '.';

const getStyles = (theme: GrafanaTheme2) => {
  return {
    container: css({
      textOverflow: 'ellipsis',
    }),
    header: css({
      label: 'header',
      cursor: 'pointer',
      overflow: 'hidden',
      padding: '0.25em 0.1em',
      textOverflow: 'ellipsis',
      whiteSpace: 'nowrap',
    }),
    headerLabel: css({
      width: '120px',
      display: 'inline-block',
    }),
    headerEmpty: css({
      label: 'headerEmpty',
      background: 'none',
      cursor: 'initial',
    }),
    headerHighContrast: css({
      label: 'headerHighContrast',
      '&:hover': {
        background: theme.colors.action.hover,
      },
    }),
    emptyIcon: css({
      label: 'emptyIcon',
      color: theme.colors.text.secondary,
    }),
  };
};

export type AccordionKeyValuesProps = {
  className?: string | TNil;
  data: TraceKeyValuePair[];
  logName?: string;
  highContrast?: boolean;
  interactive?: boolean;
  onlyValues?: boolean;
  showSummary?: boolean;
  showCountBadge?: boolean;
  isOpen: boolean;
  label: string | React.ReactNode;
  linksGetter?: (pairs: TraceKeyValuePair[], index: number) => KeyValuesTableLink[];
  onToggle?: null | (() => void);
  promoGetter?: AttributePluginPromoGetter;
  datasourceType?: string;
  openLinksInSameTab?: boolean;
};

export default function AccordionKeyValues({
  className = null,
  data,
  logName,
  highContrast = false,
  interactive = true,
  isOpen,
  label,
  linksGetter,
  onlyValues = false,
  showSummary = true,
  showCountBadge = false,
  onToggle = null,
  promoGetter,
  datasourceType,
  openLinksInSameTab,
}: AccordionKeyValuesProps) {
  const isEmpty = (!Array.isArray(data) || !data.length) && !logName;
  const styles = useStyles2(getStyles);
  const iconCls = cx(alignIcon, { [styles.emptyIcon]: isEmpty });
  let arrow: React.ReactNode | null = null;
  let headerProps: {} | null = null;
  const tableFields = logName ? [{ key: 'event name', value: logName }, ...data] : data;
  if (interactive) {
    arrow = isOpen ? (
      <Icon name={'angle-down'} className={iconCls} />
    ) : (
      <Icon name={'angle-right'} className={iconCls} />
    );
    headerProps = {
      'aria-checked': isOpen,
      onClick: isEmpty ? null : onToggle,
      role: 'switch',
    };
  }

  const showDataSummaryFields = showSummary && data.length > 0 && !isOpen;

  return (
    <div className={cx(className, styles.container)}>
      <div
        className={cx(styles.header, {
          [styles.headerEmpty]: isEmpty,
          [styles.headerHighContrast]: highContrast && !isEmpty,
        })}
        {...headerProps}
        data-testid="AccordionKeyValues--header"
      >
        {arrow}
        <strong data-test={markers.LABEL} className={styles.headerLabel}>
          {label}
          {showCountBadge ? <Counter value={data.length} variant="secondary" /> : null}
        </strong>
        {showDataSummaryFields && (
          <span className={css({ marginLeft: '0.7em' })}>
            <KeyValuesSummary data={data} />
          </span>
        )}
      </div>
      {isOpen && (
        <KeyValuesTable
          data={tableFields}
          linksGetter={linksGetter}
          onlyValues={onlyValues}
          promoGetter={promoGetter}
          datasourceType={datasourceType}
          openLinksInSameTab={openLinksInSameTab}
        />
      )}
    </div>
  );
}
